import re
from datetime import date

# Numeric: year-first (YYYY sep MM sep DD), e.g. 2022/11/30, 2022-11-30, 2022.11.30
_NUM_YMD = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")

# Numeric: day-first (DD sep MM sep YYYY), e.g. 05/03/2024 -> 2024-03-05
_NUM_DMY = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})")

# Compact: YYYYMMDD, e.g. 20241105
_NUM_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})")

# Textual: "5 March 2024", "5th Mar. 2024", "5 March, 2024"
_TXT_DMY = re.compile(r"(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\.?,?\s+(\d{4})")

# Textual: "March 5, 2024", "Mar 5th 2024", "Sept. 5, 2024"
_TXT_MDY = re.compile(r"([A-Za-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})")

# Leading weekday: "Tuesday, March 5, 2024", "Tue. 5 March 2024"
_LEADING_WORD = re.compile(r"([A-Za-z]+)\.?,?\s+(.+)")

_WEEKDAYS = {
    "monday", "mon",
    "tuesday", "tue", "tues",
    "wednesday", "wed",
    "thursday", "thu", "thur", "thurs",
    "friday", "fri",
    "saturday", "sat",
    "sunday", "sun",
}

_MONTH_NAMES = [
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
]
_MONTHS = {}
for _i, _name in enumerate(_MONTH_NAMES, start=1):
    _MONTHS[_name] = _i
    _MONTHS[_name[:3]] = _i
_MONTHS["sept"] = 9


def _to_iso(year: int, month: int, day: int):
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return None


def _month_number(name: str):
    return _MONTHS.get(name.lower())


def _strip_weekday(text: str) -> str:
    m = _LEADING_WORD.fullmatch(text)
    if m and m.group(1).lower() in _WEEKDAYS:
        return m.group(2).strip()
    return text


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = " ".join(s.strip().split())
    if not text:
        return "INVALID"

    text = _strip_weekday(text)

    m = _NUM_YMD.fullmatch(text)
    if m:
        y, _, mo, d = m.groups()
        return _to_iso(int(y), int(mo), int(d)) or "INVALID"

    m = _NUM_DMY.fullmatch(text)
    if m:
        d, _, mo, y = m.groups()
        return _to_iso(int(y), int(mo), int(d)) or "INVALID"

    m = _NUM_COMPACT.fullmatch(text)
    if m:
        y, mo, d = m.groups()
        return _to_iso(int(y), int(mo), int(d)) or "INVALID"

    m = _TXT_DMY.fullmatch(text)
    if m:
        d, mon, y = m.groups()
        mo = _month_number(mon)
        if mo:
            return _to_iso(int(y), mo, int(d)) or "INVALID"
        return "INVALID"

    m = _TXT_MDY.fullmatch(text)
    if m:
        mon, d, y = m.groups()
        mo = _month_number(mon)
        if mo:
            return _to_iso(int(y), mo, int(d)) or "INVALID"
        return "INVALID"

    return "INVALID"

import datetime
import re

_MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
}
_MONTH_FULL = {
    1: "january", 2: "february", 3: "march", 4: "april", 5: "may", 6: "june",
    7: "july", 8: "august", 9: "september", 10: "october", 11: "november", 12: "december",
}

_WEEKDAYS = {
    "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday",
    "mon", "tue", "tues", "wed", "thu", "thur", "thurs", "fri", "sat", "sun",
}

_YMD_SEP = re.compile(r"(\d{4})([-/. ])(\d{1,2})\2(\d{1,2})")
_DMY_SEP = re.compile(r"(\d{1,2})([-/. ])(\d{1,2})\2(\d{4})")
_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})")
_DAY_MONTH_NAME = re.compile(
    r"(?:the\s+)?(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?([a-z]+)\.?,?\s+(\d{4})"
)
_MONTH_NAME_DAY = re.compile(
    r"([a-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})"
)
_LEADING_WEEKDAY = re.compile(r"^([a-z]+)\.?,?\s+(.+)$")
_TRAILING_WEEKDAY = re.compile(r"^(.+?)[,\s]*\(?([a-z]+)\)?\.?$")


def _month_from_name(name: str):
    """Return month number for a full or 3+ letter English month name, else None."""
    if len(name) < 3:
        return None
    m = _MONTHS.get(name[:3])
    if m is None:
        return None
    full = _MONTH_FULL[m]
    if name == full or full.startswith(name):
        return m
    return None


def _strip_weekday(t: str) -> str:
    """Remove a single leading or trailing weekday name, if present."""
    m = _LEADING_WEEKDAY.match(t)
    if m and m.group(1) in _WEEKDAYS:
        return m.group(2).strip()
    m = _TRAILING_WEEKDAY.match(t)
    if m and m.group(2) in _WEEKDAYS:
        return m.group(1).strip().rstrip(",").strip()
    return t


def _build(y: int, m: int, d: int):
    """Return an ISO date string if (y, m, d) is a real calendar date, else None."""
    try:
        return datetime.date(y, m, d).isoformat()
    except (ValueError, OverflowError):
        return None


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = " ".join(s.strip().lower().split())
    if not t:
        return "INVALID"

    t = _strip_weekday(t)
    if not t:
        return "INVALID"

    # Year-first numeric: 2021-03-05, 2021/3/5, 2021.03.05, 2021 03 05
    m = _YMD_SEP.fullmatch(t)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(3)), int(m.group(4))
        return _build(y, mo, d) or "INVALID"

    # Compact: 20210305
    m = _COMPACT.fullmatch(t)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        return _build(y, mo, d) or "INVALID"

    # Year-last numeric: day-first by default (05/03/2024 -> 5 March 2024).
    # Month-first only when the second number cannot be a month
    # (03/25/2024 -> 25 is not a month, so read as March 25).
    m = _DMY_SEP.fullmatch(t)
    if m:
        a, b, y = int(m.group(1)), int(m.group(3)), int(m.group(4))
        if b > 12 and a <= 12:
            mo, d = a, b
        else:
            d, mo = a, b
        return _build(y, mo, d) or "INVALID"

    # Day + month name + year: 5 march 2021, 5th of March 2021, the 5th of march, 2021
    m = _DAY_MONTH_NAME.fullmatch(t)
    if m:
        d, mo = int(m.group(1)), _month_from_name(m.group(2))
        if mo is not None:
            return _build(int(m.group(3)), mo, d) or "INVALID"
        return "INVALID"

    # Month name + day + year: march 5, 2021 / mar 5 2021 / march 5th, 2021
    m = _MONTH_NAME_DAY.fullmatch(t)
    if m:
        mo, d = _month_from_name(m.group(1)), int(m.group(2))
        if mo is not None:
            return _build(int(m.group(3)), mo, d) or "INVALID"
        return "INVALID"

    return "INVALID"

import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

# Optional leading weekday, e.g. "Tuesday, ", "Tue. ", "Thurs "
_WEEKDAY_PREFIX = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues|tue|wed|thurs|thur|thu|fri|sat|sun)\.?,?\s+",
    re.IGNORECASE,
)
# YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (separator must be consistent)
_YMD_SEP = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")
# YYYYMMDD
_YMD_COMPACT = re.compile(r"(\d{4})(\d{2})(\d{2})")
# DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY (day first; separator must be consistent)
_DMY_SEP = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})")
# Month DD, YYYY  /  Mon. DD YYYY  /  Month DDth, YYYY
_MDY_NAME = re.compile(
    r"([A-Za-z]+)\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})",
    re.IGNORECASE,
)
# DD Month YYYY  /  DDth Mon. YYYY  /  DD Month, YYYY
_DMY_NAME = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\.?,?\s+(\d{4})",
    re.IGNORECASE,
)


def _build(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _month_number(name: str):
    return _MONTHS.get(name.lower())


def _normalize(s: str) -> str:
    text = " ".join(s.strip().split())
    text = _WEEKDAY_PREFIX.sub("", text, count=1)
    return text.strip()


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = _normalize(s)
    if not text:
        return "INVALID"

    m = _YMD_SEP.fullmatch(text)
    if m:
        return _build(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    m = _YMD_COMPACT.fullmatch(text)
    if m:
        return _build(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    m = _DMY_SEP.fullmatch(text)
    if m:
        return _build(int(m.group(4)), int(m.group(3)), int(m.group(1)))

    m = _MDY_NAME.fullmatch(text)
    if m:
        month = _month_number(m.group(1))
        if month is None:
            return "INVALID"
        return _build(int(m.group(3)), month, int(m.group(2)))

    m = _DMY_NAME.fullmatch(text)
    if m:
        month = _month_number(m.group(2))
        if month is None:
            return "INVALID"
        return _build(int(m.group(3)), month, int(m.group(1)))

    return "INVALID"
